global.set('takMissionGuid', msg.missionGuid);
const takServerUrl = env.get('TAK_SERVER_URL');
const missionApiPort = env.get('MISSION_API_PORT');
const guidCoTendpoint = `/Marti/api/missions/guid/${msg.missionGuid}/cot`;
msg.url=`https://${takServerUrl}:${missionApiPort}${guidCoTendpoint}`
msg.header = {'accept':'*/*'};
msg.tlsConfig = global.get('takTLSConfig');
msg.method = 'GET';
return msg;

/* jshint esversion: 8, node: true */
try {
    const mappings = JSON.parse(msg.payload);

    const takToCaltopo = {};
    const caltopoToTak = {};

    // Pass 1 — fullPath keys (custom iconset icons) and caltopoToTak (by iconLabel)
    mappings.forEach(function(m) {
        // caltopoToTak: keyed by iconLabel, first entry wins
        if (m.iconLabel && !caltopoToTak[m.iconLabel]) {
            caltopoToTak[m.iconLabel] = m;
        }

        // fullPath key: only when both iconsetUid and iconName are non-empty strings
        if (m.iconsetUid && m.iconName) {
            var folder = m.iconsetFolder || '';
            // Lowercase the full path so lookups are case-insensitive.
            // TAK may send folder names with different capitalisation than icon-configs.
            var key = (folder
                ? m.iconsetUid + '/' + folder + '/' + m.iconName
                : m.iconsetUid + '/' + m.iconName).toLowerCase();
            takToCaltopo[key] = m;
        }
    });

    // Pass 2 — cotType keys.
    // Entries with null/empty iconsetUid are "direct cotType → Caltopo icon" mappings
    // and should ALWAYS win over entries that also happen to share a cotType but are
    // primarily indexed by their fullPath.
    var cotTypeDirect = {};   // null-iconsetUid entries (win)
    var cotTypeFallback = {}; // entries with iconset data (only used if no direct entry)

    mappings.forEach(function(m) {
        if (!m.cotType) return;
        if (!m.iconsetUid) {
            // Direct mapping — always wins (last direct entry for a cotType wins)
            cotTypeDirect[m.cotType] = m;
        } else {
            // Has iconset data — only use as cotType fallback
            if (!cotTypeFallback[m.cotType]) cotTypeFallback[m.cotType] = m;
        }
    });

    // Merge: direct wins, then fallback fills gaps
    Object.keys(cotTypeFallback).forEach(function(ct) {
        if (!cotTypeDirect[ct]) cotTypeDirect[ct] = cotTypeFallback[ct];
    });
    Object.keys(cotTypeDirect).forEach(function(ct) {
        takToCaltopo[ct] = cotTypeDirect[ct];
    });

    global.set('takToCaltopo', takToCaltopo);
    global.set('caltopoToTak', caltopoToTak);

    node.status({ fill: 'green', shape: 'dot', text: 'Loaded ' + mappings.length + ' mappings' });
    return msg;
} catch (e) {
    node.error('Startup Logic Error: ' + e.message);
}

/* jshint esversion: 8, node: true */

// Input:  msg.payload is raw CoT XML containing <events><event/>...</events>
// Output: msg.payload = { features: [GeoJSON Feature, ...], xml: [xml, ...] }
//
// Pre-sanitize any attribute-less <usericon/> (TAK Server emits this for
// drawn features that don't carry an iconset reference). node-cot's schema
// requires _attributes on a usericon element and throws otherwise (often
// with an empty error message), dropping the whole feature.

const rawXml = msg.payload || "";
const eventMatches = rawXml.match(/<event[\s\S]*?<\/event>/g);

if (!eventMatches || eventMatches.length === 0) {
    node.warn("No <event> blocks found.");
    msg.payload = { features: [], xml: [] };
    return msg;
}

function stripEmptyUsericon(xml) {
    return xml
        .replace(/<usericon\s*\/>/g, '')              // <usericon/>
        .replace(/<usericon\s*>\s*<\/usericon>/g, ''); // <usericon></usericon>
}

const features = [];
const xmls = [];

for (const eventXml of eventMatches) {
    const cleanXml = eventXml.replace(/<\/?events>/g, "").trim();
    const sanitized = stripEmptyUsericon(cleanXml);
    const standalone = '<?xml version="1.0" encoding="UTF-8"?>\n' + sanitized;
    try {
        const c = new CoT(standalone);
        const gj = c.to_geojson();
        // node-cot converts the first slash in iconsetpath to a colon
        // (uid:folder/name). Fix it back to uid/folder/name.
        if (gj.properties && gj.properties.icon && gj.properties.icon.includes(':')) {
            gj.properties.icon = gj.properties.icon.replace(':', '/');
        }
        features.push(gj);
        xmls.push(c.to_xml());
    } catch (e) {
        node.warn('CoT parse failed: ' + (e.message || '(empty)') + ' | uid: ' +
            (cleanXml.match(/uid='([^']+)'/) || [])[1]);
    }
}

msg.payload = { features, xml: xmls };
return msg;

/* jshint esversion: 8, node: true */

// Map TAK CoT properties onto the same 28-property shape the Caltopo
// hash function uses, so both sides produce matching hashes for the
// same logical feature.
//
// KEY: marker-symbol MUST be set to the translated Caltopo iconLabel here,
// not the raw cotType string. Otherwise the hash stored in the DB will
// never match what Caltopo returns, causing the UPSERT to fire on every
// poll and triggering the Caltopo→TAK overwrite loop.

const intToHex = (n) => {
    if (n === undefined || n === null) return undefined;
    const v = (typeof n === 'string') ? parseInt(n, 10) : n;
    if (!Number.isFinite(v)) return undefined;
    const rgb = (v >>> 0) & 0xFFFFFF;
    return '#' + rgb.toString(16).padStart(6, '0');
};

const input = msg.payload && msg.payload.features ? msg.payload.features : [];
const normalized = [];

// Icon translation helper — same logic as sync01splitRetToCalto
const iconMap = global.get('takToCaltopo') || {};

function takIconToCaltopoLabel(rawIcon, cotType) {
    // rawIcon from node-cot: "uid:folder/name" (custom) or "a-h-G" (standard)
    if (rawIcon && rawIcon.includes(':')) {
        // Custom iconset path — normalize colon separator to slash
        // globalizer stores fullPath keys lowercase — normalize lookup the same way
        var slashIcon = rawIcon.replace(':', '/').toLowerCase();
        var entry = iconMap[slashIcon] || iconMap[slashIcon + '.png'];
        if (entry) return entry.iconLabel;
    } else if (rawIcon && rawIcon.includes('/') && !rawIcon.match(/^[a-z]-/)) {
        // Already slash-separated custom path
        var slashIcon = rawIcon.toLowerCase();
        var entry = iconMap[slashIcon] || iconMap[slashIcon + '.png'];
        if (entry) return entry.iconLabel;
    }
    // Standard CoT type (e.g. "a-h-G") or custom path not in map — fall back to cotType key
    if (cotType) {
        var entry = iconMap[cotType];
        if (entry) return entry.iconLabel;
    }
    // Unmapped: return raw cotType so the hash has SOMETHING deterministic
    return cotType || null;
}

for (const f of input) {
    if (!f || !f.geometry || !f.geometry.coordinates) continue;
    const p = f.properties || {};

    // Compute the Caltopo-style marker-symbol now so the DB hash matches
    // what we will push to Caltopo. If p already has a Caltopo marker-symbol
    // (shouldn't happen on TAK path) honour it; otherwise translate.
    const markerSymbol = p['marker-symbol'] || takIconToCaltopoLabel(p.icon || '', p.type || '');

    const out = {
        title:       p.callsign,
        description: p.remarks,
        'marker-color':   p['marker-color'] || intToHex(p.marker_color),
        'marker-symbol':  markerSymbol,
        color:            p.color,
        stroke:           p.stroke,
        'stroke-opacity': p['stroke-opacity'],
        'stroke-width':   p['stroke-width'],
        fill:             p.fill,
        'fill-opacity':   p['fill-opacity'],
        // Remaining 18 Caltopo-shape slots — undefined so they hash as null
        number:                undefined,
        primaryFrequency:      undefined,
        preparedBy:            undefined,
        timeAllocated:         undefined,
        operationalPeriodId:   undefined,
        priority:              undefined,
        unresponsivePOD:       undefined,
        transportation:        undefined,
        responsivePOD:         undefined,
        teamSize:              undefined,
        letter:                undefined,
        cluePOD:               undefined,
        resourceType:          undefined,
        secondaryFrequency:    undefined,
        status:                undefined,
        location:              undefined,
        instructions:          undefined,
        // Preserve original TAK payload for conflict detection and icon round-trip
        _tak: p
    };

    normalized.push({
        id:       f.id || p.uid || p.id,
        geometry: f.geometry,
        properties: out
    });
}

msg.payload = { features: normalized };
return msg;

/* jshint esversion: 8, node: true */

// Byte-for-byte mirror of `Create Caltopo Hash` — same MD5, same
// 28-property canonical order, same 2D coord forcing, same
// jsonb_array_elements SQL pattern. Only differences:
//   - operates on the normalized TAK feature array
//   - stamps last_sync_source = 'TAK'

const features = msg.payload && msg.payload.features ? msg.payload.features : [];
const mapID = msg.mapID || env.get("CALTOPO_MAP_ID");

const processedData = [];

features.forEach(f => {
    if (!f.geometry || !f.geometry.coordinates) return;
    const props = f.properties || {};
    let geom = JSON.parse(JSON.stringify(f.geometry));

    if (geom.type === "Point") {
        geom.coordinates = [geom.coordinates[0], geom.coordinates[1]];
    } else if (geom.type === "LineString" || geom.type === "MultiPoint") {
        geom.coordinates = geom.coordinates.map(c => [c[0], c[1]]);
    } else if (geom.type === "Polygon") {
        geom.coordinates = geom.coordinates.map(ring => ring.map(c => [c[0], c[1]]));
    }

    const stateString = JSON.stringify([
        geom.coordinates,
        props.title,
        props.number,
        props.primaryFrequency,
        props.preparedBy,
        props.timeAllocated,
        props.operationalPeriodId,
        props.priority,
        props.unresponsivePOD,
        props.transportation,
        props.responsivePOD,
        props.teamSize,
        props.letter,
        props.cluePOD,
        props.resourceType,
        props.secondaryFrequency,
        props.status,
        props.description,
        props.color,
        props['marker-symbol'],
        props['marker-color'],
        props.fill,
        props['fill-opacity'],
        props.stroke,
        props['stroke-opacity'],
        props['stroke-width'],
        props.location,
        props.instructions
    ]);

    const hash = crypto.createHash('md5').update(stateString).digest('hex');

    processedData.push({
        map_id: mapID,
        feature_id: f.id,
        geometry: geom,
        properties: props,
        hash: hash
    });
});

const sql = `
WITH incoming_data AS (
    SELECT 
        (feat->>'map_id') as m_id,
        (feat->>'feature_id') as f_id,
        ST_SetSRID(ST_GeomFromGeoJSON(feat->'geometry'), 4326) as f_geom,
        (feat->'properties')::jsonb as f_props,
        (feat->>'hash') as f_hash
    FROM jsonb_array_elements($1::jsonb) AS feat
)
INSERT INTO public.caltopo_maps (map_id, feature_id, geom, properties, last_hash, last_sync_source, seen_on_tak_at, updated_at)
SELECT m_id, f_id, f_geom, f_props, f_hash, 'TAK', now(), now()
FROM incoming_data
ON CONFLICT (map_id, feature_id)
DO UPDATE SET
    geom = EXCLUDED.geom,
    properties = EXCLUDED.properties,
    last_hash = EXCLUDED.last_hash,
    last_sync_source = 'TAK',
    seen_on_tak_at = now(),
    updated_at = now()
WHERE public.caltopo_maps.last_hash IS DISTINCT FROM EXCLUDED.last_hash
  AND (
    -- TAK wins unless this record is Caltopo-owned AND Caltopo is newer
    public.caltopo_maps.last_sync_source IS DISTINCT FROM 'CALTOPO'
    OR COALESCE(
        EXTRACT(epoch FROM (EXCLUDED.properties->'_tak'->>'time')::timestamptz) * 1000,
        0
    ) >= COALESCE(
        (public.caltopo_maps.properties->>'-updated-on')::bigint,
        0
    )
  )
RETURNING feature_id, ST_AsGeoJSON(geom)::jsonb as geom, properties, last_sync_source, caltopo_id;
`;

msg.payload = sql;
msg.queryParameters = [JSON.stringify(processedData)];
return msg;

/* jshint esversion: 8, node: true */
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) return null;

const mapID   = msg.mapID || env.get('CALTOPO_MAP_ID');
const credKey = env.get('CALTOPO_CREDENTIAL_KEY');
const credId  = env.get('CALTOPO_CREDENTIAL_ID');
const baseUrl = env.get('BASE_CALTOPO_URL') || 'https://caltopo.com';
const iconMap = global.get('takToCaltopo') || {};

const msgs = [];

for (const row of rows) {
    if (!row || !row.geom) continue;

    const props       = row.properties || {};
    // _tak holds the original node-cot GeoJSON properties preserved by the normalizer
    const tak         = props._tak || {};
    const objectClass = row.geom.type === 'Point' ? 'Marker' : 'Shape';

    // ── Icon translation (TAK → Caltopo) ──────────────────────────────────
    const cotType      = tak.type || props.type || '';
    const rawIcon      = tak.icon || '';
    const caltopoToTak = global.get('caltopoToTak') || {};

    // Priority 0: the normalizer already computed the correct Caltopo iconLabel and
    // stored it as marker-symbol. Use it directly IF it maps to a real custom iconset
    // (caltopoToTak entry has iconsetUid). This handles the case where _tak was lost
    // (Caltopo UPSERT overwrote properties) but the normalizer had already set a good label.
    const storedSymbol = props['marker-symbol'];
    const storedEntry  = storedSymbol ? caltopoToTak[storedSymbol] : null;
    let markerSymbol = (storedEntry && storedEntry.iconsetUid) ? storedSymbol : undefined;

    if (!markerSymbol) {
        // Priority 1: derive from the TAK custom icon path in _tak.icon
        // tak.icon format from node-cot: "uid:folder/name" (colon) or "uid/folder/name" (slash after batch fix)
        // icon-configs keys:             "uid/folder/name.png"
        const slashIcon   = rawIcon.includes(':') ? rawIcon.replace(':', '/') : rawIcon;
        const isCustomPath = rawIcon && (rawIcon.includes(':') || (rawIcon.includes('/') && !rawIcon.match(/^[a-z]-/)));

        if (isCustomPath) {
            // globalizer stores fullPath keys lowercase — normalize lookup the same way
            const slashIconLC = slashIcon.toLowerCase();
            var e1 = iconMap[slashIconLC] || iconMap[slashIconLC + '.png'];
            if (e1) markerSymbol = e1.iconLabel;
        }

        // Priority 2: cotType fallback (standard 2525B icons, null-iconsetUid direct mappings)
        if (!markerSymbol && cotType) {
            var e2 = iconMap[cotType];
            if (e2) markerSymbol = e2.iconLabel;
        }
    }

    // ── Build Caltopo properties ───────────────────────────────────────────
    const outProps = {
        title:             props.title       || tak.callsign || row.feature_id,
        description:       props.description || tak.remarks  || '',
        'marker-color':    props['marker-color'],
        'marker-symbol':   markerSymbol,   // omitted below if undefined
        'marker-size':     props['marker-size'] || '1',
        'marker-rotation': props['marker-rotation'] || null,
        stroke:            props.stroke,
        'stroke-width':    props['stroke-width'],
        'stroke-opacity':  props['stroke-opacity'],
        fill:              props.fill,
        'fill-opacity':    props['fill-opacity'],
        folderId:          props.folderId || null,
        class:             objectClass
    };
    Object.keys(outProps).forEach(k => { if (outProps[k] === undefined) delete outProps[k]; });

    // ── Always POST to /{objectClass}/{feature_id} ────────────────────────
    const featureId = row.feature_id;
    const endpoint  = '/api/v1/map/' + mapID + '/' + objectClass + '/' + featureId;

    const feature = {
        type: 'Feature',
        id: featureId,
        geometry: row.geom,
        properties: outProps
    };

    const expires = Date.now() + 2 * 60 * 1000;
    const body    = JSON.stringify(feature);
    const message = 'POST ' + endpoint + '\n' + expires + '\n' + body;
    const secret  = Buffer.from(credKey, 'base64');
    const sig     = crypto.createHmac('sha256', secret).update(message).digest('base64');

    const params = querystring.stringify({
        id: credId, expires: String(expires), signature: sig, json: body
    });

    msgs.push({
        ...msg,
        url:     baseUrl + endpoint,
        method:  'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        payload: params
    });
}

return [msgs];

