const state    = msg.payload.result.state;
const features = state.features || [];
const mapID    = msg.mapID;

// Build folder ID → title map from Caltopo state
const folderMap = {};
(state.folders || []).forEach(function(folder) {
    const fid   = folder.id;
    const title = (folder.properties && folder.properties.title) || folder.title || '';
    if (fid) folderMap[fid] = title;
});

// Folder names that indicate GPS track logs — skip entirely
// Matches: Tracks, Tracklogs, Track Logs (case-insensitive, exact folder title)
const TRACK_FOLDER_RE = /^(tracks|tracklogs|track\s+logs)$/i;

// Feature classes splintered to output 2 for separate normalizing (not hashed here)
const SPLINTER_CLASSES = new Set(['AppTrack', 'Assignment', 'Clue','MapMediaObject']);

const processedData      = [];
const splinteredFeatures = [];

features.forEach(f => {
    // 1. Skip features with no geometry (prevents XX000 error)
    if (!f.geometry || !f.geometry.coordinates) return;

    const props  = f.properties || {};
    const fclass = props.class  || '';

    // 2. Filter: skip features whose folder title matches a track-log pattern
    const folderTitle = folderMap[props.folderId] || '';
    if (TRACK_FOLDER_RE.test(folderTitle)) return;

    // 3. Splinter AppTrack / Assignment / Clue to output 2 for further normalizing
    if (SPLINTER_CLASSES.has(fclass)) {
        splinteredFeatures.push(f);
        return;
    }

    let geom = JSON.parse(JSON.stringify(f.geometry)); // Deep copy

    // 4. Force Geometry to 2D (PostGIS safety)
    if (geom.type === 'Point') {
        geom.coordinates = [geom.coordinates[0], geom.coordinates[1]];
    } else if (geom.type === 'LineString' || geom.type === 'MultiPoint') {
        geom.coordinates = geom.coordinates.map(c => [c[0], c[1]]);
    } else if (geom.type === 'Polygon') {
        geom.coordinates = geom.coordinates.map(ring => ring.map(c => [c[0], c[1]]));
    } 

    // 5. Generate Hash for change detection (28-property canonical order)
    const stateString = JSON.stringify([
        geom.coordinates,
        props.title,
        props.number,
        props.primaryFrequency,
        props.preparedBy,
        props.timeAllocated,
        props.operationalPeriodId,
        props.priority,
        props.unresponsivePOD,
        props.transportation,
        props.responsivePOD,
        props.teamSize,
        props.letter,
        props.cluePOD,
        props.resourceType,
        props.secondaryFrequency,
        props.status,
        props.description,
        props.color,
        props['marker-symbol'],
        props['marker-color'],
        props.fill,
        props['fill-opacity'],
        props.stroke,
        props['stroke-opacity'],
        props['stroke-width'],
        props.location,
        props.instructions
    ]);

    const hash = crypto.createHash('md5').update(stateString).digest('hex');

    processedData.push({
        map_id:     mapID,
        feature_id: f.id,
        geometry:   geom,
        properties: props,
        hash:       hash
    });
});

// 6. Deduplicate by feature_id (Caltopo sometimes returns the same ID twice)
const dedupeMap = new Map();
processedData.forEach(d => dedupeMap.set(d.feature_id, d));
const dedupedData = [...dedupeMap.values()];

// 7. Build the UPSERT SQL
const sql = `
WITH incoming_data AS (
    SELECT
        (feat->>'map_id') as m_id,
        (feat->>'feature_id') as f_id,
        ST_SetSRID(ST_GeomFromGeoJSON(feat->'geometry'), 4326) as f_geom,
        (feat->'properties')::jsonb as f_props,
        (feat->>'hash') as f_hash
    FROM jsonb_array_elements($1::jsonb) AS feat
)
INSERT INTO public.caltopo_maps
    (map_id, feature_id, geom, properties, last_hash, last_sync_source, seen_on_caltopo_at, updated_at)
SELECT m_id, f_id, f_geom, f_props, f_hash, 'CALTOPO', now(), now()
FROM incoming_data
ON CONFLICT (map_id, feature_id)
DO UPDATE SET
    geom             = CASE WHEN public.caltopo_maps.last_hash IS DISTINCT FROM EXCLUDED.last_hash THEN EXCLUDED.geom             ELSE public.caltopo_maps.geom             END,
    properties       = CASE WHEN public.caltopo_maps.last_hash IS DISTINCT FROM EXCLUDED.last_hash THEN EXCLUDED.properties       ELSE public.caltopo_maps.properties       END,
    last_hash        = CASE WHEN public.caltopo_maps.last_hash IS DISTINCT FROM EXCLUDED.last_hash THEN EXCLUDED.last_hash        ELSE public.caltopo_maps.last_hash        END,
    last_sync_source = CASE
        WHEN public.caltopo_maps.last_sync_source = 'TAK' THEN 'TAK'
        ELSE 'CALTOPO'
    END,
    seen_on_caltopo_at = now(),
    updated_at         = now()
WHERE public.caltopo_maps.last_hash IS DISTINCT FROM EXCLUDED.last_hash
RETURNING feature_id, ST_AsGeoJSON(geom)::jsonb as geom, properties, last_sync_source;
`;

msg.payload           = sql;
msg.queryParameters   = [JSON.stringify(dedupedData)];
msg.currentCaltopoIds = [
