}));

const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) return null;

const now   = new Date();
const stale = new Date(now.getTime() + 30 * 60 * 1000);
const fmt   = d => d.toISOString().replace(/\.\d{3}Z$/, '.00Z');
const esc   = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const takMission  = msg.takMission;
let   missionGuid = msg.missionGuid;
if (!missionGuid && takMission) {
    const missions = global.get('TAK_MISSIONS') || {};
    missionGuid = missions[takMission];
}

const hexToArgb = (hex, op) => {
    const rgb = parseInt((hex || '#ffffff').replace('#','').padStart(6,'0'), 16);
    const a   = Math.round((op !== undefined ? parseFloat(op) : 1.0) * 255);
    return ((a << 24) | rgb) << 0;
};

const missionDest = takMission
    ? '<marti><dest mission="' + esc(takMission) + '"/></marti>'
    : '';

const caltopoMap = global.get('caltopoToTak') || {};

const msgs = [];

for (const row of rows) {
    // TAK is always authoritative for TAK-originated features.
    // The TAK→Caltopo direction handles pushing them; we must never
    // push them back from the Caltopo side or we create an overwrite loop.
    if (row.last_sync_source === 'TAK') continue;

    const _p = row.properties || {};

    // Skip GPS track logs from Caltopo. Recognized by:
    //   - properties.class === 'AppTrack'  (native Caltopo track class)
    //   - properties.name matching '[N:Track]' (Caltopo's naming for imported
    //     GPS tracks, e.g. "RANGER03-AZDPS [1:Track]")
    // TODO: tracks will get handled separately and emitted as PLI CoT.
    if (_p.class === 'AppTrack') {
        node.warn('sync05: skipping AppTrack ' + row.feature_id + ' (' + (_p.title || '-') + ')');
        continue;
    }
    if (typeof _p.name === 'string' && /\[\d+:Track\]/.test(_p.name)) {
        node.warn('sync05: skipping imported track ' + row.feature_id + ' (' + _p.name + ')');
        continue;
    }

    const takProps = (row.properties || {})._tak || {};

    const uid  = row.feature_id;
    const geom = row.geom;
    if (!geom) continue;
    const p     = row.properties || {};
    const title = p.title || uid;

    let cotXml;
    if (geom.type === 'Point') {
        const lon = geom.coordinates[0];
        const lat = geom.coordinates[1];

        // ── Icon translation (Caltopo → TAK) ────────────────────────────
        // p['marker-symbol'] is the Caltopo iconLabel stored in the DB.
        // Look it up in caltopoToTak to get the CoT type + iconset path.
        const iconLabel = p['marker-symbol'];
        const iconEntry = iconLabel ? caltopoMap[iconLabel] : null;
        // Fall back to _tak fields when this was originally a TAK feature
        const cotType = (iconEntry && iconEntry.cotType) || takProps.type || 'a-u-G-U-C';
        const cotHow  = takProps.how || 'h-g-i-g-o';

        let iconsetTag = '';
        if (iconEntry && iconEntry.iconsetUid && iconEntry.iconName) {
            // TAK iconsetpath format: uid/folder/name.png — WITH the .png extension.
            // Evidence: CoTs received FROM TAK always include .png in the icon path
            // (e.g. "uid/WildFire/Incident Command Post.png"). TAK uses the full
            // filename to locate the icon file in the installed iconset.
            const iconName = iconEntry.iconName; // keep .png
            const iconsetPath = iconEntry.iconsetFolder
                ? iconEntry.iconsetUid + '/' + iconEntry.iconsetFolder + '/' + iconName
                : iconEntry.iconsetUid + '/' + iconName;
            iconsetTag = '<usericon iconsetpath="' + esc(iconsetPath) + '"/>';
        }

        const argb = hexToArgb(p['marker-color'], 1.0);
        cotXml = '<?xml version="1.0" encoding="UTF-8"?>\n' +
            '<event version="2.0"' +
            ' uid="'   + esc(uid)     + '"' +
            ' type="'  + esc(cotType) + '"' +
            ' how="'   + esc(cotHow)  + '"' +
            ' time="'  + fmt(now)     + '"' +
            ' start="' + fmt(now)     + '"' +
            ' stale="' + fmt(stale)   + '"' +
            ' access="Undefined">\n' +
            '  <point lat="' + lat + '" lon="' + lon + '" hae="0" ce="9999999.0" le="9999999.0"/>\n' +
            '  <detail>\n' +
            '    <contact callsign="' + esc(title) + '"/>\n' +
            '    <remarks>' + esc(p.description || '') + '</remarks>\n' +
            '    <color argb="' + argb + '"/>\n' +
            (iconsetTag ? '    ' + iconsetTag + '\n' : '') +
            '    <archive/>\n' +
            (missionDest ? '    ' + missionDest + '\n' : '') +
            '  </detail>\n' +
            '</event>';
    } else {
        const coords = geom.type === 'LineString' ? geom.coordinates : geom.coordinates[0];
        const clat = coords.reduce(function(s,c){ return s+c[1]; }, 0) / coords.length;
        const clon = coords.reduce(function(s,c){ return s+c[0]; }, 0) / coords.length;
        const strokeArgb = hexToArgb(p.stroke, p['stroke-opacity']);
        const fillArgb   = hexToArgb(p.fill,   p['fill-opacity']);
        const links = coords.map(function(c,i){
            return '  <link point="' + c[1] + ',' + c[0] + ',0"' +
                   ' uid="' + esc(uid) + '.' + i + '"' +
                   ' callsign="" type="b-m-p-c" remarks="" relation="c"/>';
        }).join('\n');
        cotXml = '<?xml version="1.0" encoding="UTF-8"?>\n' +
            '<event version="2.0"' +
            ' uid="'   + esc(uid) + '"' +
            ' type="u-d-f" how="h-e"' +
            ' time="'  + fmt(now)   + '"' +
            ' start="' + fmt(now)   + '"' +
            ' stale="' + fmt(stale) + '"' +
            ' access="Undefined">\n' +
            '  <point lat="' + clat + '" lon="' + clon + '" hae="0" ce="9999999.0" le="9999999.0"/>\n' +
            '  <detail>\n' +
            // link waypoints must come first in <detail> for TAK to render the shape
            links + '\n' +
            '    <contact callsign="' + esc(title) + '"/>\n' +
            '    <remarks>' + esc(p.description || '') + '</remarks>\n' +
            '    <strokeColor value="' + strokeArgb + '"/>\n' +
            '    <strokeWeight value="' + (p['stroke-width'] || 2) + '"/>\n' +
            '    <fillColor value="' + fillArgb + '"/>\n' +
            '    <labels_on value="false"/>\n' +
            '    <archive/>\n' +
            (missionDest ? '    ' + missionDest + '\n' : '') +
            '  </detail>\n' +
            '</event>';
    }

    msgs.push({ ...msg, payload: cotXml, cotUid: uid, missionGuid: missionGuid, lastSyncSource: row.last_sync_source });
}

return [msgs];

