    ctx.counts.caltopo_features += 1;
    if (msg.statusCode && msg.statusCode >= 400) {
        ctx.counts.caltopo_errors += 1;
        ctx.errorDetails = ctx.errorDetails || [];
        ctx.errorDetails.push(captureError('caltopo', msg));
    }
