    ctx.counts.tak_features += 1;
    if (msg.statusCode && msg.statusCode >= 400) {
        ctx.counts.tak_errors += 1;
        ctx.errorDetails = ctx.errorDetails || [];
        ctx.errorDetails.push(captureError('tak', msg));
    }
