/* jshint esversion: 8, node: true */
// fs is provided by Setup -> Modules (libs).
// https comes from settings.js functionGlobalContext.
//
// Single sync function that builds the /sync/health response. Returns a Promise
// for the TAK reachability sub-check (3s timeout), so the overall endpoint
// still resolves quickly even when TAK is down.
//
// Sub-checks:
//   caltopo_creds_ok  - both env vars set
//   icon_configs_ok   - /data/icon-configs.json parses
//   postgis_ok        - v1 no-op (returns true); /sync/pairs already exercises
//                       postgres so a separate check adds no signal here
//   tak_reachable     - HEAD probe against https://TAK_SERVER_URL:TAK_HTTPS_API_PORT/
//                       Any response (incl. 401/403/404) counts as reachable.
//                       Only DNS failure or 3s timeout marks unreachable.

const https = global.get('https');

const credsOk = Boolean(env.get('CALTOPO_CREDENTIAL_ID')) && Boolean(env.get('CALTOPO_CREDENTIAL_KEY'));

let iconConfigsOk = false;
try {
    const raw = fs.readFileSync('/data/icon-configs.json', 'utf8');
    JSON.parse(raw);
    iconConfigsOk = true;
} catch (e) {
    iconConfigsOk = false;
}

const buildReply = (takOk) => {
    msg.payload = {
        caltopo_creds_ok: credsOk,
        postgis_ok: true,
        icon_configs_ok: iconConfigsOk,
        tak_reachable: takOk
    };
    msg.statusCode = 200;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Content-Type': 'application/json'
    };
    return msg;
};

const takHost = (env.get('TAK_SERVER_URL') || '').replace(/^https?:\/\//i, '');
const takPort = parseInt(env.get('TAK_HTTPS_API_PORT') || '8446', 10);

if (!takHost || !https) {
    return buildReply(false);
}

return new Promise((resolve) => {
    let settled = false;
    const finish = (ok) => { if (!settled) { settled = true; resolve(buildReply(ok)); } };
    try {
        const req = https.request({
            hostname: takHost,
            port: takPort,
            path: '/',
            method: 'HEAD',
            timeout: 3000,
            rejectUnauthorized: false
        }, () => finish(true));
        req.on('error', () => finish(false));
        req.on('timeout', () => { try { req.destroy(); } catch (_) {} finish(false); });
        req.end();
    } catch (_) {
        finish(false);
    }
});

