// /sync/health builder. TAK reachability = certless HEAD to
// https://TAK_SERVER_URL:TAK_HTTPS_API_PORT/ ; any response (incl 401/403/404)
// counts as reachable. Only DNS failure / 3s timeout marks unreachable.

const credsOk = Boolean(env.get('CALTOPO_CREDENTIAL_ID')) && Boolean(env.get('CALTOPO_CREDENTIAL_KEY'));

let iconConfigsOk = false;
try {
    JSON.parse(fs.readFileSync('/data/icon-configs.json', 'utf8'));
    iconConfigsOk = true;
} catch (e) {
    iconConfigsOk = false;
}

const buildReply = (takOk) => {
    msg.payload = {
        caltopo_creds_ok: credsOk,
        postgis_ok: true,
        icon_configs_ok: iconConfigsOk,
        tak_reachable: takOk
    };
    msg.statusCode = 200;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Content-Type': 'application/json'
    };
    return msg;
};

const takHost = (env.get('TAK_SERVER_URL') || '').replace(/^https?:\/\//i, '');
const takPort = parseInt(env.get('TAK_HTTPS_API_PORT') || '8446', 10);

if (!takHost || !https) {
    node.warn('TAK probe early-exit: takHost=' + takHost + ' httpsType=' + (typeof https));
    return buildReply(false);
}

node.warn('TAK probe -> ' + takHost + ':' + takPort + ' (https.request=' + (typeof https.request) + ')');

return new Promise((resolve) => {
    let settled = false;
    const finish = (ok) => { if (!settled) { settled = true; resolve(buildReply(ok)); } };
    try {
        const req = https.request({
            hostname: takHost,
            port: takPort,
            path: '/',
            method: 'HEAD',
            timeout: 3000,
            rejectUnauthorized: false
        }, (res) => {
            node.warn('TAK probe OK status ' + res.statusCode);
            finish(true);
        });
        req.on('error', (e) => { node.warn('TAK probe error: ' + e.message); finish(false); });
        req.on('timeout', () => { node.warn('TAK probe TIMEOUT'); try { req.destroy(); } catch (_) { } finish(false); });
        req.end();
    } catch (e) {
        node.warn('TAK probe threw: ' + e.message);
        finish(false);
    }
